import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { canonicalDecisionDigest, verifyDecisionContract } from './d10-decision-digest.mjs';
import { sha256 } from './github-evidence.mjs';

// Generated by the actual application Core at 58b18b2 via
// JsonSerializer.Deserialize<AQGreenD10Decision>(bytes, AQGreenB6CanonicalEvidence.Options)
// followed by AQGreenB6CanonicalEvidence.Digest(decision). No private input.
const applicationDigest = '9a56eb2e908215cce23399bad2896fd8e1087b424ae9524fcfcccad83ef49f37';
const bytes = readFileSync(new URL('./d10-decision-digest/representative-decision.json', import.meta.url));

test('producer matches actual application .NET typed canonicalization and changed decision fails the binding', () => {
  assert.equal(canonicalDecisionDigest(bytes), applicationDigest);
  assert.notEqual(sha256(bytes), applicationDigest, 'raw file pin is a distinct hash');
  const changed = Buffer.from(bytes.toString('utf8').replace('"tenantId": 1', '"tenantId": 2'));
  assert.notEqual(canonicalDecisionDigest(changed), applicationDigest);
  assert.equal(canonicalDecisionDigest(bytes), applicationDigest);
});

test('nested members, placements, sorted dictionaries and UTC fractional dates match application Core', () => {
  const nested = JSON.parse(bytes);
  nested.decisionReference = 'synthetic-über-Δ';
  nested.populationDigests = { z: 'aaa', a: 'bbb' };
  nested.populationParticipantKeys = { z: ['second', 'first'], a: [] };
  nested.historicalMembers = [{ customerId: 123, participantId: '7afde7c9-a3c2-4758-ab87-5b22572412b1',
    areaId: 'b94e5b9e-8888-4444-aabb-321233aa9911', componentDigest: '9'.repeat(64),
    participantSnapshotKey: 'test' }];
  nested.reconciledPlacements = [{ placementId: '8afde7c9-a3c2-4758-ab87-5b22572412b1',
    participantId: '7afde7c9-a3c2-4758-ab87-5b22572412b1',
    placementTreeScopeId: 'b94e5b9e-8888-4444-aabb-321233aa9911', parentParticipantId: null,
    slot: 1, canonicalPath: '01', placedAtUtc: '2026-11-01T01:02:03.1234567Z', rulesVersion: 'test' }];
  assert.equal(canonicalDecisionDigest(Buffer.from(JSON.stringify(nested))),
    'b902cbbe85e6aec8e6e90e4f2ebd07880b94d15fb75c1ba1081912858bec0703');
});

test('missing or unpinned application source cannot become a canonical contract', () => {
  for (const source of [undefined, '', '/unavailable/source'])
    assert.throws(() => verifyDecisionContract(source, 'a'.repeat(40)),
      /BACKEND_DECISION_CANONICAL_CONTRACT_UNVERIFIED/);
  assert.throws(() => verifyDecisionContract('/unavailable/source', 'not-a-sha'),
    /BACKEND_DECISION_CANONICAL_CONTRACT_UNVERIFIED/);
});

test('invalid input fails without revealing bytes or parser exceptions', () => {
  const secret = Buffer.from('{"contractVersion":"secret-test-only","unexpected":"sensitive"}');
  assert.throws(() => canonicalDecisionDigest(secret), error =>
    error.message === 'BACKEND_DECISION_CANONICAL_DIGEST_UNAVAILABLE' &&
    !error.message.includes('sensitive'));
});
